#include "data_ring_contract.h"
#include <cstdio>
#include <cstdlib>
#include <algorithm>

void require(bool value, const char* label) {
  if (!value) { std::fprintf(stderr, "FAIL %s\n", label); std::exit(1); }
}
int main() {
  using namespace bridge_data;
  uint64_t cases = 0;
  for (uint32_t capacity=2; capacity<=67; ++capacity) {
    for (uint64_t begin=0; begin<capacity*8; ++begin) {
      for (uint64_t n=0; n<=capacity+1; ++n) {
        for (bool blob : {false,true}) {
          auto r=plan(begin,capacity,n,blob);
          auto fast=planAt(begin,static_cast<uint32_t>(begin%capacity),capacity,n,blob);
          require(r.valid==fast.valid && r.end==fast.end && r.words==fast.words && r.payload==fast.payload,"cached position equivalent");
          if (!r.valid) { continue; }
          require(r.end-begin==r.words && r.words<=capacity,"occupied span");
          if (blob) { require(static_cast<uint64_t>(r.payload)+n-1<=capacity,"contiguous payload"); }
          for (uint64_t consumed=begin>capacity?begin-capacity:0; consumed<=begin; ++consumed) {
            const bool expected=r.words<=capacity-(begin-consumed);
            require(available(r.end,consumed,capacity)==expected,"no overwrite");
            ++cases;
          }
        }
      }
    }
  }
  for (uint32_t capacity = 2; capacity <= 129; ++capacity) {
    for (uint32_t pos = 0; pos < capacity; ++pos) {
      for (uint64_t words = 0; words <= capacity + 1; ++words) {
        const auto r = contiguousAt(capacity * 3 + pos, pos, capacity, words);
        require(r.valid == (words <= capacity - pos), "declared layout tail fit");
        if (!r.valid && words <= capacity) {
          const auto padding = plan(capacity * 3 + pos, capacity, capacity - pos, false);
          const auto restarted = contiguousAt(padding.end, 0, capacity, words);
          require(padding.valid && restarted.valid && restarted.words == words, "padding then complete layout");
        }
      }
    }
  }
  require(!contiguousAt(UINT64_MAX, 0, 8, 1).valid, "declared layout cursor overflow");
  require(!plan(UINT64_MAX,8,1,false).valid,"cursor overflow");
  uint64_t packetCases = 0;
  for (uint32_t capacity=2; capacity<=35; ++capacity) {
    for (uint32_t position=0; position<capacity; ++position) {
      for (uint64_t prefix=0; prefix<=8; ++prefix) {
        for (size_t bytes=0; bytes<=capacity*4; ++bytes) {
          const uint64_t begin=capacity*3+position;
          const auto actual=packetAt(begin,position,capacity,prefix,bytes,true);
          const auto first=plan(begin,capacity,prefix,false);
          uint64_t words=0; blobWords(bytes,words);
          const auto last=first.valid?plan(first.end,capacity,words,true):Reservation {};
          const bool valid=first.valid && last.valid && last.end-begin<=capacity;
          require(actual.valid==valid,"whole packet valid span");
          if (valid) {
            require(actual.end==last.end && actual.words==last.end-begin
              && actual.payload==last.payload,"whole packet equals incremental layout");
          }
          ++packetCases;
        }
      }
    }
  }
  require(!packetAt(UINT64_MAX-1,2,8,2,1,true).valid,"whole packet overflow");
  uint64_t packetEdgeCases = 0;
  for (uint32_t capacity : {0u,1u,2u,67u,UINT32_MAX-1,UINT32_MAX}) {
    for (uint32_t position : {0u,capacity/2,capacity?capacity-1:0u,capacity}) {
      for (uint64_t prefix : {uint64_t(0),uint64_t(1),uint64_t(capacity/2),uint64_t(capacity),uint64_t(capacity)+1,UINT64_MAX}) {
        for (size_t bytes : {size_t(0),size_t(1),size_t(3),size_t(4),size_t(UINT32_MAX)}) {
          for (uint64_t begin : {uint64_t(0),uint64_t(1),UINT64_MAX-capacity,UINT64_MAX-1,UINT64_MAX}) {
            for (bool blob : {false,true}) {
              const auto actual=packetAt(begin,position,capacity,prefix,bytes,blob);
              const auto first=planAt(begin,position,capacity,prefix,false);
              Reservation expected=first;
              if (first.valid && blob) {
                const uint64_t next=position+prefix;
                uint64_t words=0; blobWords(bytes,words);
                expected=planAt(first.end,static_cast<uint32_t>(next>=capacity?next-capacity:next),capacity,words,true);
                if (expected.valid && expected.end-begin>capacity) {expected.valid=false;}
              }
              require(actual.valid==expected.valid,"whole packet extreme validity");
              if (expected.valid) {
                require(actual.end==expected.end && actual.words==expected.end-begin && actual.payload==expected.payload,
                  "whole packet extreme incremental equivalence");
              }
              ++packetEdgeCases;
            }
          }
        }
      }
    }
  }
  if constexpr (sizeof(size_t)>4) {
    require(!packetAt(0,0,UINT32_MAX,0,static_cast<size_t>(UINT32_MAX)+1,true).valid,"whole packet native wire overflow");
  }
  require(!plan(UINT64_MAX-2,8,4,true).valid,"padding overflow");
  uint64_t words=0;
  require(blobWords(0,words) && words==1,"zero-length prefix");
  require(blobWords(UINT32_MAX,words) && words==1073741825ULL,"uint32 boundary");
  if constexpr (sizeof(size_t)>4) { require(!blobWords(static_cast<size_t>(UINT32_MAX)+1,words),"native to wire overflow"); }
  Control c{}; c.magic=Magic;c.version=Version;c.bytes=sizeof(c);c.capacity=8;
  require(compatible(c,8),"matching protocol");
  ++c.version;require(!compatible(c,8),"protocol rejection");--c.version;
  // Progress before registration: the second read sees it; no OS wait is needed.
  unsigned reads=0, waits=0;
  auto progress=[&](){ return ++reads==1?uint64_t(0):uint64_t(4); };
  require(waitForSpace(c,12,8,progress,[&](){++waits;return false;},[](){return true;}),"registration recheck");
  require(reads==2 && waits==0 && c.waiting.load()==0,"stale progress never blocks");
  // During/after registration, coalesced and duplicate tokens do not grant space.
  for(unsigned tokens=0;tokens<7;++tokens) {
    c.consumed=0;waits=0;
    require(waitForSpace(c,12,8,[&](){return c.consumed.load();},[&](){
      ++waits; if(waits==tokens+1){ c.consumed=4; } return true;
    },[](){return true;}),"eventual progress");
    require(waits==tokens+1,"spurious wake does not permit overwrite");
  }
  // Dropped notification: a bounded wait ends; the final condition wins.
  c.consumed=0;
  require(waitForSpace(c,12,8,[&](){return c.consumed.load();},[&](){c.consumed=4;return false;},[](){return true;}),"dropped wake recheck");
  c.consumed=0;
  require(!waitForSpace(c,12,8,[&](){return c.consumed.load();},[](){return false;},[](){return true;}),"timeout/stall");
  require(!waitForSpace(c,12,8,[](){return uint64_t(4);},[](){return true;},[](){return false;}),"peer exited");
  c.fault=1;
  require(!waitForSpace(c,4,8,[](){return uint64_t(0);},[](){return true;},[](){return true;}),"poison blocks fast path");
  std::printf("DATA_RING_CONTRACT_PASS checked_space_states=%llu packet_layout_cases=%llu packet_extreme_cases=%llu pointer_bits=%u\n",
    static_cast<unsigned long long>(cases),static_cast<unsigned long long>(packetCases),static_cast<unsigned long long>(packetEdgeCases),static_cast<unsigned>(sizeof(void*)*8));
}
